<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref} from 'vue'
import {formatBeijingTime} from '@papr/shared/time'
import * as api from './live-workflow'
import type {Template,RecordItem,Rule} from './live-workflow'
const templates=ref<Template[]>([]),history=ref<RecordItem[]>([])
const view=ref<'history'|'choose'|'confirm'|'detail'>('history'),selected=ref<Template|null>(null),opened=ref<RecordItem|null>(null)
const query=ref(''),status=ref(''),templateQuery=ref(''),notice=ref(''),generating=ref(false),tagFilter=ref(''),nextGenerationAt=ref<string|null>(null)
const prototypeTools=false,syncing=false
const openTemplates=computed(()=>templates.value)
const tagOptions=computed(()=>[...new Set(openTemplates.value.flatMap(t=>t.tags))])
const records=computed(()=>history.value.filter(r=>(!query.value||r.name.includes(query.value))&&(!status.value||api.statusLabel(r.status)===status.value)))
const choices=computed(()=>templates.value.filter(t=>(!templateQuery.value||`${t.name} ${t.tags.join(' ')}`.includes(templateQuery.value))&&(!tagFilter.value||t.tags.includes(tagFilter.value))))
const layoutSummary=(t:Template)=>[...new Set(t.rules.map(r=>r.kind))].map(k=>k+'每行 '+(t.columns_by_kind?.[k]??t.columns)+' 题').join(' · ')
const count=(rules:Rule[])=>rules.reduce((n,r)=>n+r.count,0)
const difficulty=(rules:Rule[])=>{const levels=[...new Set(rules.map(r=>r.difficulty))];return levels.length>1?'混合难度':levels[0]??'待配置'}
const statusLabel=api.statusLabel
function home(){view.value='history';opened.value=null;selected.value=null}
async function choose(){view.value='choose';selected.value=null;notice.value='';try{templates.value=await api.templates()}catch(e){notice.value=String(e)}}
function select(t:Template){selected.value=t;view.value='confirm';pendingKey=crypto.randomUUID()}
async function reuse(record:RecordItem){await choose();const t=templates.value.find(t=>t.id===record.templateId);if(!t){notice.value='原模板当前不可用，请重新选择。';return}select(t)}
let timer:ReturnType<typeof setTimeout>|undefined,pendingKey='',alive=true
async function refresh(){try{history.value=await api.history();nextGenerationAt.value=(await api.sessionState()).next_generation_at;if(opened.value)opened.value=history.value.find(r=>r.id===opened.value?.id)??opened.value}catch(e){notice.value=e instanceof Error?e.message:'无法读取历史'}finally{if(alive)timer=setTimeout(refresh,3000)}}
async function generate(){if(!selected.value||generating.value)return;generating.value=true;try{await api.generate(selected.value,pendingKey||crypto.randomUUID());home();history.value=await api.history();notice.value='任务已提交，完成后可下载PDF。'}catch(e){notice.value=e instanceof Error?e.message:'提交失败，请重试';}finally{generating.value=false}}
async function cancel(id:string){try{await api.cancel(id);history.value=await api.history()}catch(e){notice.value=e instanceof Error?e.message:'取消失败'}}
async function sync(){templates.value=await api.templates()}
onMounted(async()=>{try{const state=await api.session();nextGenerationAt.value=state.next_generation_at;templates.value=await api.templates();await refresh()}catch(e){notice.value=e instanceof Error?e.message:'服务暂不可用'}})
onUnmounted(()=>{alive=false;if(timer)clearTimeout(timer)})
</script>

<template>
 <div class="practice-shell">
  <header class="practice-header"><a href="#" @click.prevent="home" class="practice-brand"><span>纸</span><strong>纸上练</strong></a><span class="practice-tagline">把练习留在纸上，把时间留给思考。</span></header>
  <main class="practice-main">
   <p v-if="nextGenerationAt">上次成功后的下次可生成时间：{{formatBeijingTime(nextGenerationAt)}}</p>
   <p v-if="notice" role="status" class="practice-notice">{{notice}}</p>
   <template v-if="view==='history'">
    <div class="practice-title"><div><span class="eyebrow">MY PRACTICE</span><h1>练习历史</h1><p>每一次练习，都从这里继续。</p></div><button @click="choose">＋ 生成练习</button></div>
    <section class="practice-card"><div class="practice-filters"><label for="history-query">练习名称<input id="history-query" v-model="query" placeholder="搜索历史练习"></label><label for="history-status">生成状态<select id="history-status" v-model="status"><option value="">全部状态</option><option>已完成</option><option>生成中</option><option>排队中</option><option>失败</option><option>已取消</option></select></label><button class="quiet" @click="query='';status=''">重置</button></div>
     <div class="practice-table-wrap"><table><thead><tr><th>练习名称</th><th>练习内容</th><th>题数</th><th>生成时间</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="r in records" :key="r.id"><td><strong>{{r.name}}</strong><div class="template-tags"><span v-for="tag in r.tags??[]" :key="tag" class="template-tag">{{tag}}</span></div></td><td>{{new Set(r.rules.map(x=>x.point)).size}} 个二级目录<small>{{difficulty(r.rules)}}</small></td><td>{{count(r.rules)}} 题</td><td>{{formatBeijingTime(r.created)}}</td><td><span class="practice-status" :class="{done:r.status==='succeeded'}">{{statusLabel(r.status)}}</span><small v-if="r.error">{{r.error}}</small></td><td><button class="text-button" :disabled="r.status!=='succeeded'" @click="opened=r;view='detail'">查看练习</button><button class="text-button" :disabled="['queued','running'].includes(r.status)" @click="reuse(r)">{{r.status==='failed'?'重新配置':'再练一份'}}</button><button v-if="r.status==='queued'" class="text-button" @click="cancel(r.id)">取消任务</button></td></tr></tbody></table></div>
     <div v-if="!records.length" class="practice-empty"><span>▤</span><h2>{{history.length?'没有找到匹配的练习':'还没有练习记录'}}</h2><p>{{history.length?'试试其他名称或状态。':'选择一份模板，生成你的第一份练习。'}}</p><button v-if="!history.length" @click="choose">生成第一份练习</button></div><div class="practice-list-foot">共 {{records.length}} 份练习</div>
    </section>
   </template>
   <template v-else-if="view==='choose'">
    <button class="text-button back" @click="home">← 返回练习历史</button><div class="practice-title"><div><h1>选择练习模板</h1><p>按名称和标签挑选练习，选好模板即可生成。</p></div><button v-if="prototypeTools" class="quiet" :disabled="syncing" @click="sync">{{syncing?'正在同步…':'同步管理台模板'}}</button></div>
    <div class="practice-steps"><strong>1 选择模板</strong><span>→</span><span>2 确认练习</span><span>→</span><span>3 返回历史查看</span></div>
    <section class="practice-card"><div class="practice-filters"><label for="template-query">练习名称或标签<input id="template-query" v-model="templateQuery" placeholder="搜索练习名称、标签"></label><button class="quiet" @click="templateQuery='';tagFilter=''">重置</button></div><div class="template-tags"><span>标签</span><button class="filter-tag" :class="{active:!tagFilter}" @click="tagFilter=''">全部</button><button v-for="tag in tagOptions" :key="tag" class="filter-tag" :class="{active:tagFilter===tag}" @click="tagFilter=tagFilter===tag?'':tag">{{tag}}</button></div><div class="practice-table-wrap"><table><thead><tr><th>练习模板</th><th>标签</th><th>难度</th><th>题数</th><th>操作</th></tr></thead><tbody><tr v-for="t in choices" :key="t.id"><td><strong>{{t.name}}</strong><small>{{t.description}}</small></td><td><div class="template-tags"><span v-for="tag in t.tags" :key="tag" class="template-tag">{{tag}}</span></div></td><td>{{difficulty(t.rules)}}<small>{{[...new Set(t.rules.map(r=>r.difficulty))].join(' / ')}}</small></td><td>{{count(t.rules)}} 题</td><td><button :disabled="!t.available" @click="select(t)">选择模板</button></td></tr></tbody></table></div><div v-if="!choices.length" class="practice-empty"><h2>暂无匹配模板</h2><p>请调整搜索条件，或稍后再来查看。</p></div></section>
   </template>
   <template v-else-if="view==='confirm' && selected">
    <button class="text-button back" @click="view='choose'">← 返回模板列表</button><div class="practice-title"><div><h1>确认练习配置</h1><p>逐项确认，不同二级目录可以使用不同难度。</p></div></div><div class="practice-steps"><span>1 选择模板</span><span>→</span><strong>2 确认练习</strong><span>→</span><span>3 返回历史查看</span></div>
    <section class="practice-card"><h2>{{selected.name}}</h2><div class="template-tags"><span v-for="tag in selected.tags" :key="tag" class="template-tag">{{tag}}</span></div><p class="practice-help">{{selected.description}}</p><div class="practice-table-wrap"><table><thead><tr><th>二级目录</th><th>题型</th><th>难度</th><th>题数</th></tr></thead><tbody><tr v-for="(r,i) in selected.rules" :key="i"><td>{{r.point}}</td><td>{{r.kind}}</td><td><span class="practice-status">{{r.difficulty}}</span></td><td>{{r.count}} 题</td></tr></tbody></table></div><div class="practice-total"><span>{{new Set(selected.rules.map(r=>r.point)).size}} 个二级目录 · {{layoutSummary(selected)}}</span><strong>合计 {{count(selected.rules)}} 题</strong></div><footer><button class="quiet" @click="view='choose'">更换模板</button><button :disabled="generating" @click="generate">{{generating?'正在生成…':'确认生成'}}</button></footer></section>
   </template>
   <template v-else-if="view==='detail' && opened">
    <button class="text-button back" @click="home">← 返回练习历史</button><div class="practice-title"><div><h1>{{opened.name}}</h1><p>共 {{count(opened.rules)}} 题 · {{difficulty(opened.rules)}}</p></div><button @click="reuse(opened)">再练一份</button></div><section class="practice-card"><p v-if="opened.withdrawn" role="alert">此试卷已撤回，下载已关闭。</p><p v-for="note in opened.notices" :key="note" role="status">勘误：{{note}}</p><h2>练习内容</h2><div class="practice-table-wrap"><table><thead><tr><th>二级目录</th><th>题型</th><th>难度</th><th>题数</th></tr></thead><tbody><tr v-for="(r,i) in opened.rules" :key="i"><td>{{r.point}}</td><td>{{r.kind}}</td><td>{{r.difficulty}}</td><td>{{r.count}}</td></tr></tbody></table></div><div class="practice-downloads"><div><strong>学生版</strong><p>试题与答题区域</p><a v-if="opened.assets.find(a=>a.kind==='student_pdf')" :href="`/api/v2/files/${opened.assets.find(a=>a.kind==='student_pdf')!.id}`" target="_blank" rel="noopener">打开／下载PDF</a></div><div><strong>解析版</strong><p>答案与解题过程</p><a v-if="opened.assets.find(a=>a.kind==='solution_pdf')" :href="`/api/v2/files/${opened.assets.find(a=>a.kind==='solution_pdf')!.id}`" target="_blank" rel="noopener">打开／下载PDF</a></div></div></section>
   </template>
  </main>
 </div>
</template>
<style scoped>
.template-tags{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin:10px 0}.template-tags>span:first-child{font-size:12px}.template-tag{font-size:12px;padding:3px 9px;color:#438268;background:#edf6f0;border-radius:5px}.practice-shell .filter-tag{min-height:30px;padding:4px 12px;background:#f3f6f4;color:#728879;font-size:12px}.practice-shell .filter-tag.active{background:#def2e7;color:#12714e}.practice-header{display:flex;align-items:center;gap:28px;padding:20px max(24px,calc((100vw - 1200px)/2));background:white;border-bottom:1px solid var(--papr-border)}.practice-brand{display:flex;align-items:center;gap:10px;text-decoration:none;white-space:nowrap;color:var(--papr-text);font-size:22px}.practice-brand span{display:grid;place-items:center;background:#07ac8e;color:white;width:38px;height:38px;border-radius:10px}.practice-tagline{color:#88958f;flex:1;font-size:13px}.practice-main{max-width:1200px;margin:0 auto;padding:30px 24px 40px}.practice-title{display:flex;justify-content:space-between;align-items:center;gap:20px;margin:30px 0 24px}.practice-title h1{font-size:30px;margin:4px 0 8px}.practice-title p{margin:0;color:#7d8d83}.eyebrow{font-size:11px;letter-spacing:2px;color:#8d9d95}.practice-card{background:white;border:1px solid #e0e9e4;border-radius:12px;padding:26px}.practice-card h2{font-size:20px;margin-top:0}.practice-filters{display:flex;align-items:end;gap:16px;flex-wrap:wrap;margin-bottom:24px}.practice-filters label{display:flex;flex-direction:column;gap:6px;color:#71867a;font-size:12px}.practice-shell input,.practice-shell select{border:1px solid #dfe7e2;border-radius:6px;padding:9px 12px;font:inherit;min-height:40px}.practice-filters input{width:260px}.practice-shell button{border-radius:7px;font-size:14px;padding:10px 18px}.practice-shell .quiet{background:white;border:1px solid #dce6df;color:#526b5e}.practice-shell .text-button{background:transparent;color:#087563;padding:6px 8px}.back{margin-top:24px}.practice-table-wrap{overflow-x:auto}table{border-collapse:collapse;width:100%;font-size:14px;text-align:left}th{font-weight:500;font-size:12px;color:#7a8b80;background:#f7faf8}th,td{padding:17px 14px;border-bottom:1px solid #edf1ef}td small{display:block;color:#93a096;font-size:12px;margin-top:5px}td strong{font-weight:600}td:last-child{white-space:nowrap}.practice-status{display:inline-block;border-radius:5px;padding:3px 9px;background:#f0f3f1;color:#748579;font-size:12px}.practice-status.done{color:#218467;background:#eaf7f0}.practice-empty{text-align:center;padding:60px 20px;color:#879a8d}.practice-empty>span{font-size:40px;color:#9bbcaf}.practice-empty h2{color:#4c6757}.practice-list-foot{font-size:12px;color:#90a094;padding-top:20px}.practice-notice{background:#eaf6ee;padding:12px 18px;border-radius:8px;color:#277656}.practice-steps{display:flex;gap:22px;padding:16px 0 24px;color:#95a198;font-size:14px}.practice-steps strong{color:#16765a}.practice-total{margin-top:22px;padding:20px;background:#f0f8f3;display:flex;justify-content:space-between;color:#3a7b5c;border-radius:8px}.practice-help{color:#809184;font-size:13px;margin-top:18px}footer{border-top:1px solid #edf1ef;padding-top:22px;margin-top:24px;display:flex;justify-content:flex-end;gap:12px}.practice-downloads{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin-top:24px}.practice-downloads>div{padding:24px;background:#f7faf8;border:1px solid #e4ece6;border-radius:8px}.practice-downloads p{color:#83958a;font-size:13px}@media(max-width:700px){.practice-tagline{display:none}.practice-header{padding:16px;justify-content:space-between;gap:10px}.practice-main{padding:20px 14px}.practice-card{padding:16px}.practice-title{align-items:flex-start;flex-wrap:wrap}.practice-title h1{font-size:25px}.practice-filters input{width:200px}.practice-steps{gap:10px;font-size:12px}.practice-downloads{grid-template-columns:1fr}.practice-total{gap:16px;flex-wrap:wrap}}
</style>
